      {
         long val = fac[a+b];
         val = (val*invfac[a])%MOD;
         return (val*invfac[b])%MOD;
      }
      public static long power(long x, long y, long p) 
      { 
          long res = 1L;      
          x = x % p;  
          while (y > 0) 
          { 
              if((y & 1)==1) 
